// Parse code intelligence request
const request = $input.first().json;

// Validate required fields
if (!request.operation_type) {
  return [{
    json: {
      error: 'Missing required field: operation_type',
      valid_operations: ['index_code', 'learn_pattern', 'search_patterns', 'analyze_success', 'update_knowledge'],
      status: 'invalid_request'
    }
  }];
}

// Build request context
const context = {
  operation_type: request.operation_type,
  character_id: request.character_id || 'unknown',
  session_id: request.session_id || 'unknown',
  timestamp: new Date().toISOString(),
  data: request.data || {},
  options: {
    learning_mode: request.learning_mode || 'adaptive',
    analysis_depth: request.analysis_depth || 'standard',
    pattern_matching: request.pattern_matching !== false,
    success_tracking: request.success_tracking !== false
  }
};

return [{
  json: context
}];

// Handle code indexing operation
const request = $input.first().json;

if (!request.data.code_snippet || !request.data.metadata) {
  return [{
    json: {
      error: 'Missing required data for code indexing: code_snippet, metadata',
      status: 'invalid_data'
    }
  }];
}

// Extract code features
const codeFeatures = {
  code_snippet: request.data.code_snippet,
  language: request.data.metadata.language || 'python',
  character_class: request.data.metadata.character_class || 'unknown',
  character_level: request.data.metadata.character_level || 1,
  automation_type: request.data.metadata.automation_type || 'unknown',
  intent: request.data.metadata.intent || 'unknown',
  complexity: request.data.metadata.complexity || 'medium',
  success_rate: request.data.metadata.success_rate || 0,
  execution_count: request.data.metadata.execution_count || 0,
  tags: request.data.metadata.tags || [],
  dependencies: request.data.metadata.dependencies || [],
  created_at: request.data.metadata.created_at || new Date().toISOString(),
  last_updated: new Date().toISOString()
};

// Analyze code structure
const codeAnalysis = {
  functions: extractFunctions(codeFeatures.code_snippet),
  variables: extractVariables(codeFeatures.code_snippet),
  control_structures: extractControlStructures(codeFeatures.code_snippet),
  external_apis: extractExternalAPIs(codeFeatures.code_snippet),
  error_handling: hasErrorHandling(codeFeatures.code_snippet),
  documentation: hasDocumentation(codeFeatures.code_snippet)
};

function extractFunctions(code) {
  const functionRegex = /(?:def|function|class)\s+(\w+)/g;
  const functions = [];
  let match;
  while ((match = functionRegex.exec(code)) !== null) {
    functions.push(match[1]);
  }
  return functions;
}

function extractVariables(code) {
  const variableRegex = /(?:let|const|var|\w+)\s*=\s*([^;\n]+)/g;
  const variables = [];
  let match;
  while ((match = variableRegex.exec(code)) !== null) {
    variables.push(match[1].trim());
  }
  return variables;
}

function extractControlStructures(code) {
  const structures = [];
  if (code.includes('if ') || code.includes('if(')) structures.push('conditional');
  if (code.includes('for ') || code.includes('for(')) structures.push('loop');
  if (code.includes('while ') || code.includes('while(')) structures.push('loop');
  if (code.includes('try ')) structures.push('error_handling');
  return structures;
}

function extractExternalAPIs(code) {
  const apiRegex = /(?:import|from|require)\s+([\w.]+)/g;
  const apis = [];
  let match;
  while ((match = apiRegex.exec(code)) !== null) {
    apis.push(match[1]);
  }
  return apis;
}

function hasErrorHandling(code) {
  return code.includes('try') && code.includes('except') || code.includes('catch');
}

function hasDocumentation(code) {
  return code.includes('#') || code.includes("'''") || code.includes('"""');
}

return [{
  json: {
    ...request,
    operation: 'index_code',
    code_features: codeFeatures,
    code_analysis: codeAnalysis,
    indexing_strategy: 'semantic_and_structural'
  }
}];

// Handle pattern learning operation
const request = $input.first().json;

if (!request.data.pattern_data || !request.data.outcome) {
  return [{
    json: {
      error: 'Missing required data for pattern learning: pattern_data, outcome',
      status: 'invalid_data'
    }
  }];
}

// Extract pattern features
const patternFeatures = {
  pattern_id: generatePatternId(request.data.pattern_data),
  character_id: request.character_id,
  session_id: request.session_id,
  pattern_type: request.data.pattern_data.type || 'unknown',
  trigger_conditions: request.data.pattern_data.trigger_conditions || [],
  actions_taken: request.data.pattern_data.actions_taken || [],
  context: request.data.pattern_data.context || {},
  outcome: {
    success: request.data.outcome.success || false,
    effectiveness_score: request.data.outcome.effectiveness_score || 0,
    execution_time: request.data.outcome.execution_time || 0,
    errors: request.data.outcome.errors || [],
    user_feedback: request.data.outcome.user_feedback || ''
  },
  timestamp: new Date().toISOString(),
  learning_weight: calculateLearningWeight(request.data.outcome)
};

function generatePatternId(patternData) {
  const hash = require('crypto').createHash('md5');
  const patternString = JSON.stringify({
    type: patternData.type,
    triggers: patternData.trigger_conditions,
    actions: patternData.actions_taken
  });
  return hash.update(patternString).digest('hex').substring(0, 8);
}

function calculateLearningWeight(outcome) {
  let weight = 0.5; // Base weight

  if (outcome.success) weight += 0.3;
  if (outcome.effectiveness_score > 0.8) weight += 0.2;
  if (outcome.execution_time < 5000) weight += 0.1; // Fast execution
  if (outcome.errors.length === 0) weight += 0.1;
  if (outcome.user_feedback && outcome.user_feedback.includes('good')) weight += 0.1;

  return Math.min(weight, 1.0);
}

return [{
  json: {
    ...request,
    operation: 'learn_pattern',
    pattern_features: patternFeatures,
    learning_strategy: 'reinforcement_learning'
  }
}];

// Handle pattern search operation
const request = $input.first().json;

if (!request.data.search_criteria) {
  return [{
    json: {
      error: 'Missing required data for pattern search: search_criteria',
      status: 'invalid_data'
    }
  }];
}

// Build search query
const searchQuery = {
  criteria: request.data.search_criteria,
  filters: {
    character_class: request.data.search_criteria.character_class || null,
    automation_type: request.data.search_criteria.automation_type || null,
    complexity_level: request.data.search_criteria.complexity_level || null,
    success_rate_threshold: request.data.search_criteria.min_success_rate || 0.5,
    tags: request.data.search_criteria.tags || []
  },
  sort_by: request.data.search_criteria.sort_by || 'success_rate',
  limit: request.data.search_criteria.limit || 10,
  include_analysis: request.data.search_criteria.include_analysis || false
};

return [{
  json: {
    ...request,
    operation: 'search_patterns',
    search_query: searchQuery,
    search_strategy: 'semantic_similarity'
  }
}];

// Create AI analysis prompt for intelligence processing
const request = $input.first().json;

const analysisPrompt = `
You are a Code Intelligence AI that analyzes and learns from character automation patterns. Your task is to process the following operation and provide intelligent insights.

## Operation: ${request.operation}
## Character ID: ${request.character_id}
## Session ID: ${request.session_id}

${request.code_features ? `
## Code Features:
- Language: ${request.code_features.language}
- Character Class: ${request.code_features.character_class}
- Automation Type: ${request.code_features.automation_type}
- Intent: ${request.code_features.intent}
- Complexity: ${request.code_features.complexity}
- Success Rate: ${request.code_features.success_rate}
- Execution Count: ${request.code_features.execution_count}
` : ''}

${request.pattern_features ? `
## Pattern Features:
- Pattern Type: ${request.pattern_features.pattern_type}
- Success: ${request.pattern_features.outcome.success}
- Effectiveness Score: ${request.pattern_features.outcome.effectiveness_score}
- Learning Weight: ${request.pattern_features.learning_weight}
` : ''}

${request.search_query ? `
## Search Criteria:
${JSON.stringify(request.search_query, null, 2)}
` : ''}

## Analysis Required:
Based on the operation type, provide detailed analysis:

${request.operation === 'index_code' ? `
For code indexing, analyze:
1. Code quality and structure
2. Potential improvements
3. Similar successful patterns
4. Optimization opportunities
5. Documentation suggestions
` : ''}

${request.operation === 'learn_pattern' ? `
For pattern learning, analyze:
1. Pattern effectiveness and success factors
2. Improvement recommendations
3. Generalization opportunities
4. Context dependencies
5. Transferability to other scenarios
` : ''}

${request.operation === 'search_patterns' ? `
For pattern search, analyze:
1. Search optimization strategies
2. Relevance scoring criteria
3. Pattern ranking methodology
4. Contextual matching factors
5. Personalization opportunities
` : ''}

## Response Format (JSON):
{
  "analysis_summary": "Brief overview of findings",
  "key_insights": ["important discoveries"],
  "recommendations": ["actionable suggestions"],
  "patterns_identified": ["recognized patterns"],
  "success_factors": ["elements contributing to success"],
  "improvement_opportunities": ["areas for enhancement"],
  "knowledge_updates": {
    "new_patterns": ["patterns to add to knowledge base"],
    "updated_patterns": ["patterns to modify"],
    "deprecated_patterns": ["patterns to remove"]
  },
  "next_steps": ["recommended follow-up actions"]
}

Focus on actionable intelligence that improves the system's understanding and future performance.`;

return [{
  json: {
    ...request,
    deepseek_prompt: analysisPrompt,
    analysis_type: 'code_intelligence'
  }
}];

// Process AI analysis and prepare knowledge base updates
const aiResponse = $input.first().json;
const originalRequest = items.find(item => item.json.deepseek_prompt)?.json;

if (!aiResponse.choices || !aiResponse.choices[0]?.message?.content) {
  return [{
    json: {
      error: 'Invalid AI response',
      status: 'ai_error'
    }
  }];
}

try {
  const analysisResult = JSON.parse(aiResponse.choices[0].message.content);

  // Prepare knowledge base updates
  const knowledgeUpdates = {
    operation_id: generateOperationId(),
    operation_type: originalRequest.operation,
    character_id: originalRequest.character_id,
    session_id: originalRequest.session_id,
    timestamp: new Date().toISOString(),
    analysis_result: analysisResult,
    knowledge_base_updates: {
      new_patterns: analysisResult.knowledge_updates?.new_patterns || [],
      updated_patterns: analysisResult.knowledge_updates?.updated_patterns || [],
      deprecated_patterns: analysisResult.knowledge_updates?.deprecated_patterns || []
    },
    learning_insights: {
      success_factors: analysisResult.success_factors || [],
      improvement_opportunities: analysisResult.improvement_opportunities || [],
      next_steps: analysisResult.next_steps || []
    },
    metadata: {
      ai_provider: 'deepseek',
      model: 'deepseek-chat',
      tokens_used: aiResponse.usage?.total_tokens || 0,
      processing_time: Date.now() - originalRequest.timestamp
    }
  };

  function generateOperationId() {
    return 'op_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
  }

  return [{
    json: knowledgeUpdates
  }];

} catch (error) {
  return [{
    json: {
      error: 'Failed to process AI analysis',
      details: error.message,
      status: 'processing_error'
    }
  }];
}

// Prepare final response
const result = $input.first().json;

const response = {
  status: 'success',
  timestamp: new Date().toISOString(),
  operation_id: result.operation_id,
  operation_type: result.operation_type,
  character_id: result.character_id,
  session_id: result.session_id,
  analysis_summary: result.analysis_result.analysis_summary,
  key_insights: result.analysis_result.key_insights,
  recommendations: result.analysis_result.recommendations,
  patterns_updated: {
    new: result.knowledge_base_updates.new_patterns.length,
    updated: result.knowledge_base_updates.updated_patterns.length,
    deprecated: result.knowledge_base_updates.deprecated_patterns.length
  },
  learning_insights: result.learning_insights,
  next_steps: result.learning_insights.next_steps,
  metadata: {
    tokens_used: result.metadata.tokens_used,
    processing_time: result.metadata.processing_time,
    ai_provider: result.metadata.ai_provider
  }
};

return [{
  json: response
}];

// Error handling
const error = $input.first().json;

const errorResponse = {
  status: 'error',
  timestamp: new Date().toISOString(),
  error: error.error || 'Unknown error occurred',
  details: error.details || 'No additional details',
  operation_type: error.operation_type || 'unknown',
  character_id: error.character_id || 'unknown',
  session_id: error.session_id || 'unknown',
  suggestions: [
    'Check request format and required fields',
    'Ensure operation type is valid',
    'Verify data structure and completeness'
  ]
};

return [{
  json: errorResponse
}];
